begin;
do $$begin if current_database()<>'factory_lean_quality_local' or inet_server_addr()<>'127.0.0.1'::inet or inet_server_port() not in (55487,55488) then raise exception 'Disposable localhost only';end if;end$$;
truncate late_test.checks;
do $$declare x jsonb;f uuid;h private.manufactured_outputs;p jsonb;q jsonb;g uuid;r jsonb;k uuid:=gen_random_uuid();src uuid;so uuid;sl uuid;qty numeric;groups jsonb;l uuid;other uuid;
begin
 select a.x into x from output2_test.fixture a;f:=(x->>'factory')::uuid;perform set_config('request.jwt.claim.sub',x->>'owner',false);
 insert into public.sales_orders(factory_id,requested_by,created_by,requested_delivery,safety_buffer_days,status) values(f,(x->>'owner')::uuid,(x->>'owner')::uuid,clock_timestamp()+interval '3 days',0,'approved') returning id into so;
 insert into public.sales_order_lines(factory_id,order_id,product_id,quantity,unit) values(f,so,(x->>'product')::uuid,60,'meter') returning id into sl;
 insert into public.sales_incoming_allocations(factory_id,line_id,item_id,quantity) values(f,sl,(x->>'item')::uuid,60);
 r:=public.record_manufactured_output(f,output2_test.payload(x,100),gen_random_uuid());
 select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;g:=(h.recorded_groups->0->>'id')::uuid;
 perform late_test.ok(not exists(select 1 from public.finished_goods_movements where entry_id=h.entry_id),'recorded output never stock');
 perform late_test.ok((select quantity=60 from public.sales_incoming_allocations where line_id=sl),'recording retains incoming commitment');
 perform late_test.fails(format('select public.receive_manufactured_output(%L,%L,%L,1,%L)',f,h.id,jsonb_build_object('group_id',g,'quantity','1','location','QA receiving bay','physical_confirmation',true),k),'output_quality_required');
 groups:=jsonb_build_array(jsonb_build_object('id',g,'quantity','95','released','95','missing_operations','[]'::jsonb));
 q:=public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','5','reason','Five meters physically rejected'),1,gen_random_uuid());
 perform late_test.ok(private.output_pending(f,h.item_id)=95,'Quality pending finished is 95');
 perform late_test.ok((select coalesce(sum(on_hand),0)=0 from public.finished_goods_balances where factory_id=f),'release never stock');
 p:=jsonb_build_object('group_id',g,'quantity','92','location','QA receiving bay','physical_confirmation',true,'note','Three meters still at Production');
 r:=public.receive_manufactured_output(f,h.id,p,2,k);
 perform late_test.ok((select on_hand=92 and reserved=60 from public.finished_goods_balances where factory_id=f and product_id=h.product_id),'92 received once, 60 existing commitment reserved');
 perform late_test.ok((select quantity=0 and received_quantity=60 from public.sales_incoming_allocations where line_id=sl),'only received stock converts incoming');
 perform late_test.ok(private.output_received(f,h.id,g::text)=92 and private.output_pending(f,h.item_id)=3,'three pending, not loss or extra inventory');
 perform late_test.ok(public.receive_manufactured_output(f,h.id,p,2,k)=r,'receipt immutable UUID replay');
 perform late_test.fails(format('select public.receive_manufactured_output(%L,%L,%L,2,%L)',f,h.id,p||'{"quantity":"1"}',k),'request_conflict');
 perform late_test.fails(format('select public.receive_manufactured_output(%L,%L,%L,3,%L)',f,h.id,p||'{"quantity":"4"}',gen_random_uuid()),'output_receipt_quantity');
 perform late_test.fails(format('select public.supply_command(%L,''acknowledge_good'',%L,%L)',f,jsonb_build_object('entry',h.entry_id),gen_random_uuid()),'output_quantity_receipt_required');
 -- Amend only the unreceived portion; already received stock is unchanged.
 groups:=jsonb_build_array(jsonb_build_object('id',g,'quantity','94','released','94','missing_operations','[]'::jsonb));
 q:=public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','6','reason','One additional unreceived meter rejected'),3,gen_random_uuid());
 perform late_test.ok(private.output_received(f,h.id,g::text)=92 and private.output_pending(f,h.item_id)=2,'partial receipt amendment leaves credited quantity alone');
 perform public.receive_manufactured_output(f,h.id,p||'{"quantity":"2"}',4,gen_random_uuid());
 perform late_test.ok((select on_hand=94 from public.finished_goods_balances where factory_id=f and product_id=h.product_id),'subsequent receipt only credits remaining two');
 select id into src from public.finished_goods_sources where factory_id=f and entry_id=h.entry_id;
 groups:=jsonb_build_array(jsonb_build_object('id',g,'quantity','93','released','93','missing_operations','[]'::jsonb));
 perform late_test.fails(format('select public.manufactured_output_command(%L,''QUALITY'',%L,%L,5,%L)',f,h.id,jsonb_build_object('groups',groups,'rejected','7','reason','Withdraw received meter'),gen_random_uuid()),'output_stock_unavailable');
 perform public.source_stock_command(f,'identify',jsonb_build_object('source',src,'quantity','94','label','Segregated QA bay','physically_identified',true,'note','Physical stock verified'), '[]',gen_random_uuid());
 q:=public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','7','reason','Withdraw identified unreserved meter'),5,gen_random_uuid());
 perform late_test.ok((select on_hand=93 and reserved=60 from public.finished_goods_balances where factory_id=f and product_id=h.product_id),'protected compensating debit leaves reservations intact');
 perform late_test.ok(private.output_received(f,h.id,g::text)=93 and (select count(*)=1 from private.manufactured_output_adjustments where output_id=h.id),'original receipt retained with signed adjustment audit');
 groups:=jsonb_build_array(jsonb_build_object('id',g,'quantity','59','released','59','missing_operations','[]'::jsonb));
 perform late_test.fails(format('select public.manufactured_output_command(%L,''QUALITY'',%L,%L,6,%L)',f,h.id,jsonb_build_object('groups',groups,'rejected','41','reason','Cannot consume Sales commitments'),gen_random_uuid()),'output_stock_unavailable');
 perform late_test.ok((select sum(stock_delta)=93 from public.finished_goods_movements where entry_id=h.entry_id),'stock movement conservation');
 perform late_test.ok((select effective_good=100 from public.production_entries where id=h.entry_id),'Quality never rewrites technician gross');
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform late_test.fails(format('select public.receive_manufactured_output(%L,%L,%L,6,%L)',f,h.id,p,gen_random_uuid()),'permission_denied');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 -- Unfinished storage uses actual classified lots, no finished credit.
 r:=public.record_manufactured_output(f,output2_test.payload(x,0,10),gen_random_uuid());select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 select jsonb_agg(value||jsonb_build_object('released',value->>'quantity')) into groups from jsonb_array_elements(h.recorded_groups);
 perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','0','reason','Recoverable groups'),1,gen_random_uuid());
 select jsonb_agg(value order by (value->>'quantity')::numeric desc) into groups from jsonb_array_elements(groups);
 g:=(groups->0->>'id')::uuid;
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',g,'quantity','6','location','WIP bay','physical_confirmation',true),2,gen_random_uuid());
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',groups->1->>'id','quantity','4','location','WIP bay','physical_confirmation',true),3,gen_random_uuid());
 perform late_test.ok((select count(*)=2 and sum(quantity_available)=10 and sum(warehouse_quantity)=10 from public.unfinished_lots where source_entry_id=h.entry_id),'different groups remain separate, no double floor stock');
 perform late_test.ok(not exists(select 1 from public.finished_goods_movements where entry_id=h.entry_id),'unfinished never finished inventory');
 select lot_id into l from private.manufactured_output_lots where output_id=h.id and group_id=g;
 perform late_test.fails(format('select public.supply_command(%L,''receive_wip'',%L,%L)',f,jsonb_build_object('lot',l,'quantity','1'),gen_random_uuid()),'output_quantity_receipt_required');
 perform late_test.fails(format('update public.unfinished_lots set warehouse_quantity=warehouse_quantity-1 where id=%L',l),'output_completion_pending');
 groups:=jsonb_set(jsonb_set(groups,'{0,quantity}','"5"'),'{0,released}','"5"');
 perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','1','reason','Stored unused WIP damage'),4,gen_random_uuid());
 perform late_test.ok((select quantity_available=5 and warehouse_quantity=5 from public.unfinished_lots where id=l),'stored unused WIP compensates safely');
 perform late_test.ok(jsonb_array_length(public.manufactured_receiving_read(f)->'pools')=2,'separate missing-operation pools retain source lists');
 -- No activation in the installed code; this exercise used the isolated fixture override.
 perform late_test.ok(public.manufactured_output_capability(f)->>'available'='false','public capability remains inactive');
end$$;
do $$declare x jsonb;f uuid;h private.manufactured_outputs;r jsonb;p jsonb;groups jsonb;g uuid;so uuid;sl uuid;src uuid;rev bigint;other jsonb;begin
 x:=late_test.new_context('phase3-sales',3600,false);f:=(x->>'factory')::uuid;perform set_config('request.jwt.claim.sub',x->>'owner',false);
 insert into public.sales_orders(factory_id,requested_by,created_by,requested_delivery,safety_buffer_days,status) values(f,(x->>'owner')::uuid,(x->>'owner')::uuid,clock_timestamp()+interval '3 days',0,'approved') returning id into so;
 insert into public.sales_order_lines(factory_id,order_id,product_id,quantity,unit) values(f,so,(x->>'product')::uuid,60,'meter') returning id into sl;
 insert into public.sales_incoming_allocations(factory_id,line_id,item_id,quantity) values(f,sl,(x->>'item')::uuid,60);
 r:=public.record_manufactured_output(f,output2_test.payload(x,100),gen_random_uuid());select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 g:=(h.recorded_groups->0->>'id')::uuid;groups:=jsonb_set(h.recorded_groups,'{0,released}','"100"');
 perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','0','reason','Sales inspection'),1,gen_random_uuid());
 perform public.finish_product_item(f,h.item_id);
 perform late_test.ok(private.quality_production_remaining(f,h.item_id)=100,'completed execution retains unreceived supply');
 perform late_test.ok((select incoming=100 and on_hand=0 and reserved=0 and projected=40 from private.finished_inventory_projection(f) where product_id=h.product_id),'completed job forecast and Sales commitment counted once');
 perform late_test.fails(format('select public.dispatch_sales_order(%L,%L,%L,%L)',f,so,sl,gen_random_uuid()),'fulfillment_hold');
 p:=jsonb_build_object('group_id',g,'quantity','20','location','Sales bay','physical_confirmation',true);
 perform public.receive_manufactured_output(f,h.id,p,2,gen_random_uuid());
 perform late_test.ok((select quantity=40 and received_quantity=20 from public.sales_incoming_allocations where line_id=sl),'partial receipt converts only twenty of sixty incoming');
 perform late_test.ok((select on_hand=20 and reserved=20 and incoming=80 and projected=40 from private.finished_inventory_projection(f) where product_id=h.product_id),'partial receipt does not double count incoming');
 perform public.receive_manufactured_output(f,h.id,p||'{"quantity":"80"}',3,gen_random_uuid());
 select id into src from public.finished_goods_sources where entry_id=h.entry_id;
 perform public.source_stock_command(f,'identify',jsonb_build_object('source',src,'quantity','100','label','Sales bay segregated source','physically_identified',true),'[]',gen_random_uuid());
 perform public.source_stock_command(f,'dispatch',jsonb_build_object('sales_order',so,'line',sl),jsonb_build_array(jsonb_build_object('source_id',src,'sales_line_id',sl,'quantity','60')),gen_random_uuid());
 perform late_test.ok((select on_hand=40 and reserved=0 from public.finished_goods_balances where factory_id=f),'existing source-selected dispatch conserves received stock');
 groups:=jsonb_build_array(jsonb_build_object('id',g,'quantity','50','released','50','missing_operations','[]'::jsonb));
 perform late_test.fails(format('select public.manufactured_output_command(%L,''QUALITY'',%L,%L,4,%L)',f,h.id,jsonb_build_object('groups',groups,'rejected','50','reason','Already dispatched source is unavailable'),gen_random_uuid()),'output_stock_unavailable');
 perform late_test.ok((select quantity_available=40 from public.finished_goods_sources where id=src),'failed amendment cannot consume dispatched quantity');
 other:=late_test.new_context('phase3-isolation',3600,false);perform set_config('request.jwt.claim.sub',other->>'owner',false);
 perform late_test.fails(format('select public.receive_manufactured_output(%L,%L,%L,4,%L)',f,h.id,p,gen_random_uuid()),'permission_denied');
end$$;
do $$declare x jsonb;f uuid;pr uuid;i uuid;h private.manufactured_outputs;r jsonb;groups jsonb;g jsonb;p jsonb;begin
 select a.x into x from output2_test.fixture a;f:=(x->>'factory')::uuid;perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform public.finish_product_item(f,(x->>'item')::uuid);
 pr:=public.create_production_request(f,'Second source demand','normal',null,'Deterministic isolated pooling fixture',jsonb_build_array(jsonb_build_object('product_id',x->>'product','quantity',100,'unit','meter')));
 select id into i from public.production_orders where request_id=pr;
 perform public.plan_product_item(f,i,(x->>'line')::uuid,date_trunc('day',clock_timestamp())+interval '3 days 3 hours');perform public.start_product_item(f,i);x:=x||jsonb_build_object('item',i);
 r:=public.record_manufactured_output(f,output2_test.payload(x,0,10),gen_random_uuid());select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 select jsonb_agg(value||jsonb_build_object('released',value->>'quantity') order by (value->>'quantity')::numeric desc) into groups from jsonb_array_elements(h.recorded_groups);
 -- Separate handling instructions prevent pooling despite the same Product.
 groups:=jsonb_set(groups,'{1,restriction}','"Keep dry and separate"');
 perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','0','reason','Second order storage'),1,gen_random_uuid());
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',groups->0->>'id','quantity','6','location','WIP bay','physical_confirmation',true),2,gen_random_uuid());
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',groups->1->>'id','quantity','4','location','WIP bay','physical_confirmation',true),3,gen_random_uuid());
 p:=public.manufactured_receiving_read(f);
 perform late_test.ok(exists(select 1 from jsonb_array_elements(p->'pools') z where z->>'quantity'='11' and jsonb_array_length(z->'sources')=2),'compatible groups pool 5+6 without losing two original orders');
 perform late_test.ok(jsonb_array_length(p->'pools')=3,'different recovery instructions remain separate');
 perform late_test.ok((select count(distinct demand_item_id)=2 from private.manufactured_output_lots where factory_id=f),'demand allocations retain both original items');
 r:=public.record_manufactured_output(f,output2_test.payload(x,0.1234567890123456789),gen_random_uuid());select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 groups:=jsonb_set(h.recorded_groups,'{0,released}','"0.1234567890123456789"');
 perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','0','reason','Exact fractional receipt'),1,gen_random_uuid());
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',groups->0->>'id','quantity','0.1234567890123456789','location','Precision bay','physical_confirmation',true),2,gen_random_uuid());
 perform late_test.ok((select stock_delta=0.1234567890123456789 from public.finished_goods_movements where entry_id=h.entry_id),'receipt preserves 19 decimal places');
end$$;
-- The relationship is seeded only in this rollback fixture: Phase 4 task
-- creation is deliberately out of scope. All recording/receiving uses commands.
do $$declare x jsonb;c jsonb;f uuid;pr uuid;i uuid;h private.manufactured_outputs;r jsonb;groups jsonb;begin
 x:=late_test.new_context('phase3-replacement',3600,false);f:=(x->>'factory')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform public.record_manufactured_output(f,output2_test.payload(x,50),gen_random_uuid());
 pr:=public.create_production_request(f,'Linked supply fixture','normal',null,'Local replacement forecast',jsonb_build_array(jsonb_build_object('product_id',x->>'product','quantity',20,'unit','meter')));
 select id into i from public.production_orders where request_id=pr;
 update public.production_orders set replacement_original_item_id=(x->>'item')::uuid where id=i;
 perform public.plan_product_item(f,i,(x->>'other_line')::uuid,date_trunc('day',clock_timestamp())+interval '3 days 3 hours');
 perform late_test.ok(private.quality_production_remaining(f,(x->>'item')::uuid)=80 and private.quality_production_remaining(f,i)=20,'linked planned replacement nets future execution only');
 perform public.start_product_item(f,i);c:=x||jsonb_build_object('item',i,'line',x->>'other_line');
 r:=public.record_manufactured_output(f,output2_test.payload(c,20),gen_random_uuid());
 select * into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 groups:=jsonb_set(h.recorded_groups,'{0,released}','"20"');
 perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',groups,'rejected','0','reason','Replacement accepted'),1,gen_random_uuid());
 perform late_test.ok(private.quality_production_remaining(f,(x->>'item')::uuid)=80 and private.quality_production_remaining(f,i)=20,'replacement produced pending counted once with original fifty pending');
 perform late_test.ok(private.quality_production_remaining(f,(x->>'item')::uuid,true)=100,'subtree includes each pending source once');
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',groups->0->>'id','quantity','20','location','Replacement bay','physical_confirmation',true),2,gen_random_uuid());
 perform late_test.ok((select on_hand=20 and incoming=80 and projected=100 from private.finished_inventory_projection(f) where product_id=h.product_id),'replacement receipt removes pending without restoring original future');
 perform public.finish_product_item(f,(x->>'item')::uuid);
 perform late_test.ok((select on_hand=20 and incoming=50 and projected=70 from private.finished_inventory_projection(f) where product_id=h.product_id),'completed original pending remains distinct from replacement supply');
end$$;
set constraints all immediate;
select count(*) assertions from late_test.checks;
rollback;
